"use client";

import { cn } from "../lib/cn";
import { MOTION_DEFAULTS, type DatePickerMotion } from "../lib/motion";
import { exitDurationForMotion, usePresence } from "../lib/presence";
import {
  eventInside,
  useFloatingPortal,
} from "../lib/use-floating-portal";
import { TimeInput, type TimeInputLook, type TimeInputSize } from "./time-input";
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";

export type TimePickerSize = TimeInputSize;
export type TimePickerLook = TimeInputLook;
export type TimePickerMotion = DatePickerMotion;

export type TimePickerProps = {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Quick picks under the control (HH:mm 24h). */
  presets?: string[];
  size?: TimePickerSize;
  look?: TimePickerLook;
  motion?: TimePickerMotion;
  hourCycle?: 24 | 12;
  minuteStep?: number;
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  disabled?: boolean;
  placeholder?: string;
  name?: string;
  id?: string;
  className?: string;
  placement?: "auto" | "bottom" | "top";
  "aria-label"?: string;
};

const DEFAULT_PRESETS = ["09:00", "12:00", "13:00", "17:00", "18:00"] as const;

const sizeClass: Record<TimePickerSize, string> = {
  sm: "sg-datepicker-trigger-sm",
  md: "",
  lg: "sg-datepicker-trigger-lg",
};

function ClockIcon() {
  return (
    <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
      <circle
        cx="10"
        cy="10"
        r="6.75"
        stroke="currentColor"
        strokeWidth="1.6"
      />
      <path
        d="M10 6.5V10l2.5 1.75"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * Atom — TimePicker
 * Trigger + portaled panel with TimeInput and optional presets.
 * Value is always 24h `HH:mm`. No timezone engine.
 */
export function TimePicker({
  value,
  defaultValue = "09:00",
  onValueChange,
  presets = [...DEFAULT_PRESETS],
  size = "md",
  look = "soft",
  motion = MOTION_DEFAULTS.datePicker,
  hourCycle = 24,
  minuteStep = 5,
  label,
  hint,
  error,
  disabled,
  placeholder = "Pick a time…",
  name,
  id,
  className,
  placement = "auto",
  "aria-label": ariaLabel,
}: TimePickerProps) {
  const reactId = useId();
  const pickerId = id ?? `sg-timepicker-${reactId}`;
  const panelId = `${pickerId}-panel`;
  const hintId = hint ? `${pickerId}-hint` : undefined;
  const errorId = error ? `${pickerId}-error` : undefined;
  const describedBy = [hintId, errorId].filter(Boolean).join(" ") || undefined;
  const invalid = Boolean(error);

  const isControlled = value !== undefined;
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const current = isControlled ? value! : uncontrolled;

  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(current);
  const { mounted: panelMounted, exiting: panelExiting, state: panelState } =
    usePresence(open, { durationMs: exitDurationForMotion(motion) });

  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  const { portalReady, floatingStyle, side: menuPlacement } = useFloatingPortal({
    open,
    mounted: panelMounted,
    triggerRef,
    panelRef,
    placement,
    align: "start",
    matchWidth: false,
    flipMinSpace: 240,
    gap: 6,
  });

  const commit = useCallback(
    (next: string) => {
      if (!isControlled) setUncontrolled(next);
      onValueChange?.(next);
    },
    [isControlled, onValueChange],
  );

  const close = useCallback(() => setOpen(false), []);

  const openPanel = useCallback(() => {
    if (disabled) return;
    setDraft(current);
    setOpen(true);
  }, [current, disabled]);

  useEffect(() => {
    if (!open || panelExiting) return;

    function onPointerDown(event: MouseEvent) {
      if (!eventInside(event.target, rootRef.current, panelRef.current)) {
        close();
      }
    }

    function onDocKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      event.preventDefault();
      close();
      triggerRef.current?.focus();
    }

    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onDocKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onDocKeyDown);
    };
  }, [close, open, panelExiting]);

  function onTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (disabled) return;
    if (
      event.key === "ArrowDown" ||
      event.key === "Enter" ||
      event.key === " "
    ) {
      event.preventDefault();
      if (!open) openPanel();
    }
  }

  function applyDraft() {
    commit(draft);
    close();
    triggerRef.current?.focus();
  }

  function pickPreset(hhmm: string) {
    setDraft(hhmm);
    commit(hhmm);
    close();
    triggerRef.current?.focus();
  }

  const control = (
    <div className="sg-timepicker-root" ref={rootRef}>
      {name ? <input type="hidden" name={name} value={current} /> : null}
      <button
        ref={triggerRef}
        id={pickerId}
        type="button"
        className={cn("sg-datepicker-trigger", sizeClass[size], className)}
        disabled={disabled}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={panelId}
        aria-invalid={invalid || undefined}
        aria-describedby={describedBy}
        aria-label={ariaLabel ?? (label ? undefined : "Time")}
        data-open={open || undefined}
        onClick={() => (open ? close() : openPanel())}
        onKeyDown={onTriggerKeyDown}
      >
        <span
          className="sg-datepicker-value"
          data-placeholder={!current || undefined}
        >
          {current || placeholder}
        </span>
        <span className="sg-datepicker-icon" aria-hidden="true">
          <ClockIcon />
        </span>
      </button>

      {panelMounted && portalReady
        ? createPortal(
            <div
              ref={panelRef}
              id={panelId}
              role="dialog"
              aria-modal="false"
              aria-label="Time picker"
              className="sg-timepicker-panel"
              data-placement={menuPlacement}
              data-motion={motion}
              data-state={panelState}
              data-portaled=""
              style={floatingStyle}
            >
              <TimeInput
                label="Time"
                value={draft}
                onValueChange={setDraft}
                size={size}
                look={look}
                hourCycle={hourCycle}
                minuteStep={minuteStep}
                fullWidth
              />
              {presets.length > 0 ? (
                <div className="sg-timepicker-presets" role="list">
                  {presets.map((p) => (
                    <button
                      key={p}
                      type="button"
                      role="listitem"
                      className="sg-timepicker-preset"
                      data-selected={p === draft || undefined}
                      onClick={() => pickPreset(p)}
                    >
                      {p}
                    </button>
                  ))}
                </div>
              ) : null}
              <div className="sg-timepicker-actions">
                <button
                  type="button"
                  className="sg-timepicker-apply"
                  onClick={applyDraft}
                >
                  Apply
                </button>
              </div>
            </div>,
            document.body,
          )
        : null}
    </div>
  );

  if (!label && !hint && !error) return control;

  return (
    <div className="sg-field">
      {label ? (
        <label className="sg-field-label" htmlFor={pickerId}>
          {label}
        </label>
      ) : null}
      {control}
      {hint && !error ? (
        <p id={hintId} className="sg-field-hint">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={errorId} className="sg-field-error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/** NumberInput shell + stepper language */
export type NumberInputLook = "soft" | "solid" | "outline" | "ghost";

/** Slider track / thumb language */
export type SliderLook = "soft" | "solid" | "glass" | "accent";

/** FileField trigger surface */
export type FileFieldLook = "solid" | "soft" | "dashed" | "ghost";

/** Progress track / fill language */
export type ProgressLook = "soft" | "solid" | "glass" | "accent" | "striped";

/** StatusDot chrome language (color still from status / color) */
export type StatusDotLook = "soft" | "solid" | "outline" | "glow";

/** Chip surface language */
export type ChipLook = "soft" | "solid" | "outline" | "glass" | "glow";

/** CloseButton chrome */
export type CloseButtonLook = "ghost" | "soft" | "solid" | "danger";

/**
 * Collapsible / Accordion disclosure surface
 * soft = frost card · solid = long content · glass = chrome · outline = border only · ghost = flush list
 */
export type CollapsibleLook = "soft" | "solid" | "glass" | "outline" | "ghost";

export type AccordionLook = CollapsibleLook;

/** Breadcrumb chrome: plain path · soft tray · pill chips */
export type BreadcrumbLook = "plain" | "soft" | "pill";

/** Pagination control chrome */
export type PaginationLook = "soft" | "solid" | "ghost" | "glass";

/** EmptyState surface */
export type EmptyStateLook = "solid" | "soft" | "outline";

/**
 * Stepper language
 * soft = frost track · solid = solid rail · outline = line only
 * dots = progress line + large dots · pills = segmented chip row
 */
export type StepperLook = "soft" | "solid" | "outline" | "dots" | "pills";

/**
 * Toolbar strip
 * soft | solid | glass | ghost | accent (accent edge rail)
 */
export type ToolbarLook = "soft" | "solid" | "glass" | "ghost" | "accent";

/** List host surface */
export type ListLook = "soft" | "solid" | "outline" | "ghost" | "inset";

/**
 * Stat metric tile
 * solid | soft | glass | outline | accent (left rail)
 */
export type StatLook = "solid" | "soft" | "glass" | "outline" | "accent";

/** PageHeader chrome: plain flush · soft frost · solid panel · glass chrome */
export type PageHeaderLook = "plain" | "soft" | "solid" | "glass";

/** SettingsSection panel chrome */
export type SettingsSectionLook = "soft" | "solid" | "glass" | "plain";

/**
 * DataTable surface language
 * soft = frost · solid = panel · glass = chrome · outline = border · ghost = flush
 */
export type DataTableLook = "soft" | "solid" | "glass" | "outline" | "ghost";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Collapsible / Accordion panel open motion. */
export type CollapsibleMotion = MotionNone | "fade" | "height";

export type AccordionMotion = CollapsibleMotion;

/** Sheet edge panel enter/exit. */
export type SheetMotion = MotionNone | "slide" | "fade";

/** HoverCard panel (Popover family). */
export type HoverCardMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
  collapsible: "height",
  accordion: "height",
  sheet: "slide",
  hoverCard: "scale",
} as const satisfies Record<string, string>;

"use client";

import { useEffect, useState } from "react";

/**
 * Unmount delay so CSS exit animations can finish.
 * Keep in sync with token exit durations (~`--sg-duration-normal` / motion-med).
 */
export const EXIT_DURATION_MS = 200;

export type PresenceOptions = {
  /** 0 = unmount immediately (motion="none" or reduced-motion). */
  durationMs?: number;
};

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Map motion recipe → exit hold time. */
export function exitDurationForMotion(motion: string | undefined): number {
  if (motion === "none") return 0;
  if (prefersReducedMotion()) return 0;
  return EXIT_DURATION_MS;
}

/**
 * Keep a node mounted while `open` is true **and** briefly after it becomes false
 * so exit keyframes can play. Mirrors Radix presence / `data-state` pattern.
 */
export function usePresence(open: boolean, options?: PresenceOptions) {
  const durationMs = options?.durationMs ?? EXIT_DURATION_MS;
  const [mounted, setMounted] = useState(open);
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }

    if (!mounted) return;

    if (durationMs <= 0) {
      setMounted(false);
      setExiting(false);
      return;
    }

    setExiting(true);
    const id = window.setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, durationMs);

    return () => window.clearTimeout(id);
  }, [open, durationMs, mounted]);

  return {
    /** Still in the DOM (open or playing exit). */
    mounted,
    /** Exit animation should run. */
    exiting,
    /** For `data-state`: open while interactive, closed while exiting. */
    state: (open && !exiting ? "open" : "closed") as "open" | "closed",
  };
}

/**
 * Viewport-aware floating coordinates for portaled overlays.
 * No Floating UI dependency — pure getBoundingClientRect math.
 */

export type FloatingSide = "top" | "bottom";
export type FloatingAlign = "start" | "center" | "end";
export type FloatingPlacement = "auto" | FloatingSide;

export type FloatingCoords = {
  top: number;
  left: number;
  side: FloatingSide;
  /** When matchWidth, panel width equals trigger (clamped to viewport). */
  width?: number;
};

export type ComputeFloatingArgs = {
  trigger: DOMRect;
  /** Measured panel size (offsetWidth / offsetHeight). */
  panelWidth: number;
  panelHeight: number;
  placement?: FloatingPlacement;
  align?: FloatingAlign;
  /** Gap between trigger and panel (px). */
  gap?: number;
  /** Viewport padding (px). */
  pad?: number;
  /**
   * Stretch panel to trigger width (Select / Combobox / MultiSelect).
   * When true, `align` is ignored for horizontal placement.
   */
  matchWidth?: boolean;
  /** Preferred flip threshold when placement is auto. */
  flipMinSpace?: number;
};

function clamp(n: number, min: number, max: number) {
  return Math.min(Math.max(n, min), max);
}

/**
 * Resolve fixed top/left for a panel relative to a trigger rect.
 * Flips top/bottom when needed; clamps left/right into the viewport.
 */
export function computeFloatingPosition({
  trigger,
  panelWidth,
  panelHeight,
  placement = "auto",
  align = "start",
  gap = 6,
  pad = 8,
  matchWidth = false,
  flipMinSpace,
}: ComputeFloatingArgs): FloatingCoords {
  const vw = typeof window !== "undefined" ? window.innerWidth : 1024;
  const vh = typeof window !== "undefined" ? window.innerHeight : 768;

  const width = matchWidth
    ? clamp(trigger.width, 0, Math.max(0, vw - pad * 2))
    : panelWidth;

  const height = panelHeight > 0 ? panelHeight : flipMinSpace ?? 220;

  const spaceBelow = vh - trigger.bottom - gap;
  const spaceAbove = trigger.top - gap;

  let side: FloatingSide;
  if (placement === "top") side = "top";
  else if (placement === "bottom") side = "bottom";
  else {
    const minSpace = flipMinSpace ?? Math.min(height, 220);
    side =
      spaceBelow < minSpace && spaceAbove > spaceBelow ? "top" : "bottom";
  }

  // If chosen side still overflows badly, prefer the roomier side.
  if (placement === "auto") {
    if (side === "bottom" && spaceBelow < height && spaceAbove > spaceBelow) {
      side = "top";
    } else if (side === "top" && spaceAbove < height && spaceBelow > spaceAbove) {
      side = "bottom";
    }
  }

  let top =
    side === "bottom" ? trigger.bottom + gap : trigger.top - height - gap;

  // Keep panel inside vertical viewport when possible.
  top = clamp(top, pad, Math.max(pad, vh - height - pad));

  let left: number;
  if (matchWidth) {
    left = trigger.left;
  } else if (align === "center") {
    left = trigger.left + trigger.width / 2 - width / 2;
  } else if (align === "end") {
    left = trigger.right - width;
  } else {
    left = trigger.left;
  }

  left = clamp(left, pad, Math.max(pad, vw - width - pad));

  return matchWidth
    ? { top, left, side, width }
    : { top, left, side };
}

"use client";

import {
  computeFloatingPosition,
  type FloatingAlign,
  type FloatingCoords,
  type FloatingPlacement,
  type FloatingSide,
} from "./floating";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useState,
  type CSSProperties,
  type RefObject,
} from "react";

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

export type UseFloatingPortalOptions = {
  /** Interactive open (not exiting-only). */
  open: boolean;
  /** Presence mounted — keep positioning while exit plays. */
  mounted: boolean;
  triggerRef: RefObject<HTMLElement | null>;
  panelRef: RefObject<HTMLElement | null>;
  placement?: FloatingPlacement;
  align?: FloatingAlign;
  matchWidth?: boolean;
  gap?: number;
  flipMinSpace?: number;
};

/**
 * Portaled overlay positioning: fixed coords + scroll/resize updates.
 * Caller still renders via createPortal(…, document.body).
 */
export function useFloatingPortal({
  open,
  mounted,
  triggerRef,
  panelRef,
  placement = "auto",
  align = "start",
  matchWidth = false,
  gap = 6,
  flipMinSpace,
}: UseFloatingPortalOptions) {
  const [portalReady, setPortalReady] = useState(false);
  const [coords, setCoords] = useState<FloatingCoords>({
    top: 0,
    left: 0,
    side: "bottom",
  });

  useEffect(() => {
    setPortalReady(true);
  }, []);

  const update = useCallback(() => {
    const trigger = triggerRef.current;
    const panel = panelRef.current;
    if (!trigger || !panel) return;

    const tRect = trigger.getBoundingClientRect();
    const next = computeFloatingPosition({
      trigger: tRect,
      panelWidth: panel.offsetWidth || tRect.width,
      panelHeight: panel.offsetHeight,
      placement,
      align,
      matchWidth,
      gap,
      flipMinSpace,
    });
    setCoords(next);
  }, [
    align,
    flipMinSpace,
    gap,
    matchWidth,
    panelRef,
    placement,
    triggerRef,
  ]);

  useIsomorphicLayoutEffect(() => {
    if (!mounted || !portalReady) return;
    update();
    // Second frame: fonts / max-height may change measured size.
    const id = window.requestAnimationFrame(() => update());
    return () => window.cancelAnimationFrame(id);
  }, [mounted, open, portalReady, update]);

  useEffect(() => {
    if (!mounted || !portalReady) return;

    function onScrollOrResize() {
      update();
    }

    window.addEventListener("resize", onScrollOrResize);
    // Capture scroll on ancestors (overflow parents).
    window.addEventListener("scroll", onScrollOrResize, true);
    return () => {
      window.removeEventListener("resize", onScrollOrResize);
      window.removeEventListener("scroll", onScrollOrResize, true);
    };
  }, [mounted, portalReady, update]);

  const floatingStyle: CSSProperties = {
    position: "fixed",
    top: coords.top,
    left: coords.left,
    ...(coords.width !== undefined ? { width: coords.width } : null),
    right: "auto",
    bottom: "auto",
    margin: 0,
  };

  return {
    portalReady,
    floatingStyle,
    side: coords.side as FloatingSide,
    update,
  };
}

/** True if event target is inside any of the given roots. */
export function eventInside(
  target: EventTarget | null,
  ...roots: Array<HTMLElement | null | undefined>
): boolean {
  if (!(target instanceof Node)) return false;
  return roots.some((root) => root?.contains(target));
}
